/* ============================================================
   SCRIPT 104 - Carga de datos MUNICIPALIDADES
   Fase 1 del 4to tipo de solicitante "Municipalidad"
   (ver v3/CLAUDE.md y script 103, que crea la tabla).
   Ejecutar conectado como SDRERC_APP. Requiere el script 103 ya
   ejecutado (tabla MUNICIPALIDADES debe existir).

   Fuente: docs/pase_produccion/municipalidades.xlsx, hoja "Hoja1"
   (1651 filas de datos) + hoja "Hoja2" (1 fila adicional,
   incorporación posterior "Se incorporó 12DIC2025") = 1652 filas
   en total. Se importan TODAS (a diferencia de centros_atencion, no
   hay un criterio de categorización para filtrar).

   Denominación calculada según el patrón acordado con el usuario
   (ver script 103 para el detalle completo).

   Idempotente mediante un único guard (todo el bloque de 1652
   INSERT corre dentro de "IF v_count = 0", solo si la tabla está
   vacía) -- mismo criterio que el script 102 para centros_atencion.
   A diferencia de ese caso, CODIGO sí es una clave natural 100%
   confiable acá (única y sin huecos en las 1652 filas), así que una
   reimportación futura de datos actualizados SÍ podría hacerse con
   MERGE por fila si hiciera falta -- se mantiene el guard simple acá
   por consistencia con el resto de scripts de este proyecto.

   No se ejecuta automáticamente: requiere autorización explícita
   antes de correr contra la base.
   ============================================================ */

DECLARE
  v_count NUMBER;
BEGIN
  SELECT COUNT(1) INTO v_count FROM municipalidades;
  IF v_count = 0 THEN
    EXECUTE IMMEDIATE 'INSERT INTO municipalidades (codigo, tipo, oficina_afiliada, ubigeo, departamento, provincia, distrito, centro_poblado, oficina_regional, implementacion, denominacion) VALUES (''508182'', ''MUNICIPALIDAD DE CENTRO POBLADO'', ''OFICINA REGISTRAL AFILIADA DE CP. TULUCE'', ''92-33-19-03-04-101'', ''PIURA'', ''HUANCABAMBA'', ''SONDOR'', ''TULUCE'', ''OFICINA REGIONAL 1 - PIURA'', ''SDTN'', ''Municipalidad de Centro Poblado Tuluce'')';
